// Strict parse: a tool call becomes a proposal; otherwise a refusal. No normalization of
// the model's chosen operation/target (the provider validates and decides).
const msg = ($input.first().json.message) || {};
const tc = (msg.tool_calls && msg.tool_calls[0]) || null;
let proposal;
if (tc && tc.function && tc.function.name === 'propose_action') {
  const a = tc.function.arguments || {};
  proposal = { operation: a.operation, target: a.target, claimed_class: a.claimed_class || null };
} else {
  proposal = { refusal: (msg.content || '(no tool call)') };
}
return [{ json: { scenario_id: 'fresh', prompt_variant_id: 'v1', model_metadata: 'qwen3:1.7b think=false temp=0 seed=42', proposal } }];
